import { MakeLogicType, actions, connect, kea, listeners, path, reducers } from 'kea'
import { router } from 'kea-router'
import posthog from 'posthog-js'

import { urls } from 'scenes/urls'

import { stashPendingAiPrompt } from '~/layout/ai/pendingAiPrompt'
import { runnerPanelLogic } from '~/layout/ai/runnerPanelLogic'

import type { ComposerPrefillRequest } from 'products/posthog_ai/frontend/api/runner'
import type { NewSessionSuggestion } from 'products/tasks/frontend/spaces/newSessionSuggestionDefaults'

export const TODAY_HOME_PANEL_ID = 'today-home'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todayHomeComposerLogicValues {
    prefillRequest: ComposerPrefillRequest | null
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todayHomeComposerLogicActions {
    handOffToClassic: (prompt: string) => {
        prompt: string
    } // runnerPanelLogic
    homeTaskStarted: (taskId: string) => {
        taskId: string
    }
    starterSuggestionSelected: (
        suggestion: NewSessionSuggestion,
        position: number
    ) => {
        position: number
        suggestion: NewSessionSuggestion
    }
}

export type todayHomeComposerLogicType = MakeLogicType<todayHomeComposerLogicValues, todayHomeComposerLogicActions>

export const todayHomeComposerLogic = kea<todayHomeComposerLogicType>([
    path(['scenes', 'project-homepage', 'today', 'todayHomeComposerLogic']),
    connect(() => ({
        actions: [runnerPanelLogic({ panelId: TODAY_HOME_PANEL_ID }), ['handOffToClassic']],
    })),
    actions({
        homeTaskStarted: (taskId: string) => ({ taskId }),
        starterSuggestionSelected: (suggestion: NewSessionSuggestion, position: number) => ({ suggestion, position }),
    }),
    reducers({
        prefillRequest: [
            null as ComposerPrefillRequest | null,
            {
                starterSuggestionSelected: (_, { suggestion }) => ({
                    prompt: suggestion.prompt,
                    mode: suggestion.mode,
                }),
            },
        ],
    }),
    listeners({
        homeTaskStarted: ({ taskId }) => {
            posthog.capture('today home task started')
            router.actions.push(urls.aiTask(taskId))
        },
        handOffToClassic: ({ prompt }) => {
            stashPendingAiPrompt(prompt)
            router.actions.push(urls.ai())
        },
        starterSuggestionSelected: ({ suggestion, position }) => {
            posthog.capture('today home starter suggestion clicked', { suggestion_id: suggestion.id, position })
        },
    }),
])
